    const c2 = Array(26).fill(0);
    function countLeaves(node, arr) {
        if (!node) return;
        if (node.val !== '+') {
            arr[node.val.charCodeAt(0) - 97]++;
        }
        countLeaves(node.left, arr);
        countLeaves(node.right, arr);
    }
    countLeaves(root1, c1);
    countLeaves(root2, c2);
